  const lines: string[] = []
  lines.push('# CSS Architecture Deep Analysis')
  lines.push('')
  lines.push('**CSS Arch Score:** ' + r.cssArchScore + '/100 | **Issues:** ' + r.totalIssues + ' | **Severity:** ' + r.severity.toUpperCase())
  lines.push('')
  lines.push('> ' + r.summary)
