  lines.push('# Container Security Analysis')
  lines.push('')
  lines.push('**Container Score:** ' + r.containerScore + '/100 | **Issues:** ' + r.totalIssues + ' | **Severity:** ' + r.severity.toUpperCase())
  lines.push('')
  lines.push('> ' + r.summary)
  lines.push('')
