  const totalIssues = aggregation.length + shaping.length
  const bffScore = Math.max(0, 100 - aggregation.length * 8 - shaping.length * 8)
  const severity: Severity = aggregation.length > 0 ? 'warning' : totalIssues > 0 ? 'info' : 'info'

