  const lines: string[] = []
  lines.push('# Payload Compression Analysis')
  lines.push('')
  lines.push('**Compression Score:** ' + r.compressionScore + '/100 | **Issues:** ' + r.totalIssues + ' | **Severity:** ' + r.severity.toUpperCase())
