  if (r.hardcodedDate.length > 0) { l.push('## Hardcoded Expiry Date (' + r.hardcodedDate.length + ')'); r.hardcodedDate.forEach(x => l.push('- Line ' + x.line + ': ' + x.suggestion)); l.push('') }
