  if (r.isolateNeeded.length > 0) { l.push('## Isolate Needed (' + r.isolateNeeded.length + ')'); r.isolateNeeded.forEach(x => l.push('- Line ' + x.line + ': ' + x.suggestion)); l.push('') }
